SELECT d_ret.d_date, CASE WHEN t.t_hour BETWEEN 6 AND 11 THEN 'Morning' WHEN t.t_hour BETWEEN 12 AND 17 THEN 'Afternoon' WHEN t.t_hour BETWEEN 18 AND 21 THEN 'Evening' ELSE 'Night' END AS hour_bucket, AVG(sr.sr_return_amt) AS avg_return_amt, SUM(sr.sr_return_tax) * 100.0 / NULLIF(SUM(sr.sr_return_amt), 0) AS avg_tax_percent, RANK() OVER (PARTITION BY d_ret.d_date ORDER BY AVG(sr.sr_return_amt) DESC) AS bucket_rank, SUM(AVG(sr.sr_return_amt)) OVER (PARTITION BY CASE WHEN t.t_hour BETWEEN 6 AND 11 THEN 'Morning' WHEN t.t_hour BETWEEN 12 AND 17 THEN 'Afternoon' WHEN t.t_hour BETWEEN 18 AND 21 THEN 'Evening' ELSE 'Night' END ORDER BY d_ret.d_date ROWS UNBOUNDED PRECEDING) AS cumulative_avg_return_amt FROM store_returns sr JOIN date_dim d_ret ON sr.sr_returned_date_sk = d_ret.d_date_sk JOIN time_dim t ON sr.sr_return_time_sk = t.t_time_sk JOIN call_center cc ON 1=1 JOIN date_dim d_open ON cc.cc_open_date_sk = d_open.d_date_sk JOIN date_dim d_close ON cc.cc_closed_date_sk = d_close.d_date_sk WHERE d_ret.d_date BETWEEN d_open.d_date AND d_close.d_date GROUP BY d_ret.d_date, CASE WHEN t.t_hour BETWEEN 6 AND 11 THEN 'Morning' WHEN t.t_hour BETWEEN 12 AND 17 THEN 'Afternoon' WHEN t.t_hour BETWEEN 18 AND 21 THEN 'Evening' ELSE 'Night' END
